raw = gzip.decompress(base64.b64decode(PACKED))
if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA:
    raise RuntimeError('Paket bütünlüğü doğrulanamadı; işlem yapılmadı.')
package=json.loads(raw.decode('utf8'))
records=package['questions']
metadata=package['metadata']
if len(records)!=100 or len({r['external_id'] for r in records})!=100:
    raise RuntimeError('Tam 100 benzersiz soru gerekli.')
FIELDS=['kind','prompt','context','options','answer','explanation','hint','difficulty','goals','base_xp','order','card_pages']

def fp(record):
    return hashlib.sha256(json.dumps(record,ensure_ascii=False,sort_keys=True).encode('utf8')).hexdigest()

def preserved_state(path):
    progress=UserPathProgress.objects.filter(path=path)
    return (progress.count(),UserPathProgress.completed.through.objects.filter(userpathprogress__path=path).count(),
            LearningSession.objects.filter(path=path).count(),QuestionAttempt.objects.filter(session__path=path).count(),
            XPTransaction.objects.filter(attempt__session__path=path).count())

with transaction.atomic():
    path=LearningPath.objects.select_for_update().get(pk=PATH_ID,owner=None)
    if path.title!=TITLE:raise RuntimeError('Hedef ID ve başlık farklı; işlem durduruldu.')
    before=preserved_state(path)
    prefs=deepcopy(path.preferences or {})
    registry=deepcopy(prefs.get(REGISTRY,{}))
    existing=list(path.questions.select_for_update().order_by('order','id'))
    current={q.pk:q for q in existing}
    mapping=registry.get('records',{})
    known_ids={item['pk'] for item in mapping.values()}
    old=[q for q in existing if q.pk not in known_ids]
    if registry and registry.get('package_sha')!=PAYLOAD_SHA:
        raise RuntimeError('Farklı v2 paket bulundu; tehlikeli overwrite engellendi.')
    shared=[q for q in old if q.paths.exclude(pk=path.pk).exists()]
    exclusive=[q for q in old if q not in shared]
    summary={'mode':'rollback' if ROLLBACK else 'dry-run' if DRY_RUN else 'apply','path_id':path.pk,
        'new_package_questions':100,'existing_items':len(existing),'retire_exclusive':[q.pk for q in exclusive],
        'detach_shared_from_target_only':[q.pk for q in shared],'reuse':len(mapping),'create':100-len(mapping),
        'delete_records':0,'reset_progress':False,'reset_xp':False,'audio_files_created':0}
    if ROLLBACK:
        if not registry:raise RuntimeError('Geri alınacak v2 aktarım kaydı bulunamadı.')
        if not registry.get('active',False):
            print('ROLLBACK ZATEN UYGULANMIŞ; kayıtlar korunuyor.')
        elif DRY_RUN:
            print(json.dumps(summary,ensure_ascii=False))
        else:
            for item in mapping.values():
                q=current.get(item['pk'])
                if not q or q.paths.exclude(pk=path.pk).exists():raise RuntimeError('Yeni içerik ilişkileri değişmiş; otomatik rollback durduruldu.')
                q.published=False;q.save(update_fields=['published'])
            for item in registry['previous']:
                q=Question.objects.get(pk=item['pk'])
                if item['shared']:
                    q.paths.add(path)
                else:
                    q.published=item['published'];q.save(update_fields=['published'])
            path.published=registry['previous_path_published']
            path.description=registry['previous_path_description']
            path.minutes=registry['previous_path_minutes']
            path.difficulty=registry['previous_path_difficulty']
            registry['active']=False;prefs[REGISTRY]=registry;path.preferences=prefs
            path.save(update_fields=['published','preferences','description','minutes','difficulty'])
            if preserved_state(path)!=before:raise RuntimeError('Tarihsel kullanıcı kayıtları değişti; geri alma iptal edildi.')
            print('ROLLBACK TAMAM: eski set yeniden görünür; v2 ve kullanıcı geçmişi korunur.')
    else:
        if registry and not registry.get('active',True):
            raise RuntimeError('v2 geri alınmış; yeniden etkinleştirme ayrı plan gerektirir.')
        for r in records:
            if r['external_id'] in mapping:
                item=mapping[r['external_id']]
                if item['digest']!=fp(r) or item['pk'] not in current:raise RuntimeError('v2 kayıt eşleştirmesi farklı; üzerine yazılmadı.')
                q=current[item['pk']]
                if any(getattr(q,k)!=r[k] for k in FIELDS) or q.answer_options.exists() or not q.published or not q.module or q.module.path_id!=path.pk or q.module.order!=r['chapter']:
                    raise RuntimeError('Admin v2 içeriğini değiştirmiş; üzerine yazılmadı.')
            elif any(q.prompt==r['prompt'] for q in existing):
                raise RuntimeError('Haritasız aynı başlıklı içerik var; duplicate engellendi.')
        if DRY_RUN:
            print(json.dumps(summary,ensure_ascii=False,indent=2))
            print('DRY-RUN: hiçbir veritabanı kaydı değiştirilmedi. 100 soru hazır.')
        else:
            if not registry:
                registry={'package_sha':PAYLOAD_SHA,'active':True,'records':{},'previous_path_published':path.published,'previous_path_description':path.description,'previous_path_minutes':path.minutes,'previous_path_difficulty':path.difficulty,
                    'previous':[{'pk':q.pk,'published':q.published,'shared':q in shared} for q in old]}
                for q in shared:q.paths.remove(path)
                for q in exclusive:
                    q.published=False;q.save(update_fields=['published'])
            modules={}
            for chapter in range(1,11):
                modules[chapter],_=Module.objects.get_or_create(path=path,title=package['chapters'][chapter-1],order=chapter)
            created=0
            for r in records:
                external_id=r['external_id']
                if external_id in mapping:continue
                fields={k:r[k] for k in FIELDS};fields.update(published=True,in_workshop=False)
                q=Question(module=modules[r['chapter']],**fields);q.full_clean();q.save();q.paths.add(path)
                registry['records'][external_id]={'pk':q.pk,'digest':fp(r),'metadata':metadata[external_id]}
                created+=1
            prefs[REGISTRY]=registry;path.preferences=prefs;path.published=True
            path.description='NEXORA’da ilk IT denetimin: 100 bağlı vaka, 10 bölüm; temelden uzman kararlarına ilerle.'
            path.minutes=180;path.difficulty='advanced'
            path.save(update_fields=['preferences','published','description','minutes','difficulty'])
            active=path.questions.filter(published=True).exclude(kind='info')
            package_ids=[item['pk'] for item in registry['records'].values()]
            if active.count()!=100 or set(active.values_list('pk',flat=True))!=set(package_ids):
                raise RuntimeError('Tam 100 aktif soru doğrulanamadı; tüm işlem geri alındı.')
            if preserved_state(path)!=before:raise RuntimeError('Kullanıcı geçmişi değişti; tüm işlem geri alındı.')
            print('YAYIN TAMAMLANDI: IT Auditor: İlk Denetimin — 100 soru, 10 bölüm.')
            print('Yeni:',created,'Tekrar kullanılan:',100-created,'Eski kayıtlar fiziksel silinmedi.')
            print('Başka yollar ve kullanıcı ilerleme/cevap/puan kayıtları korundu.')
            print('Ses dosyaları henüz yok; ilgili vakalar metinle çözülebilir.')
